    try {
        rawContent = fs.readFileSync(yamlPath, 'utf8');
    }
    catch (err) {
        return {
            name: path.basename(skillDir),
            path: skillDir,
            valid: false,
            schemaVersion: 'unknown',
            version: 'unknown',
            stateCount: 0,
            transitionCount: 0,
