            name: path.basename(skillDir),
            path: skillDir,
            valid: false,
            schemaVersion: 'unknown',
            version: 'unknown',
            stateCount: 0,
            transitionCount: 0,
            errors: [`Invalid YAML syntax: ${err.message}`],
            warnings: [],
        };
    }
    if (!parsed || typeof parsed !== 'object') {
        return {
            name: path.basename(skillDir),
            path: skillDir,
            valid: false,
            schemaVersion: 'unknown',
            version: 'unknown',
            stateCount: 0,
            transitionCount: 0,
            errors: ['skill.yaml must contain a valid YAML object mapping'],
            warnings: [],
