                    const tplPath = path.resolve(skillDir, sDef.prompt_template);
                    referencedTemplates.add(tplPath);
                    if (!fs.existsSync(tplPath)) {
                        errors.push(`State "${fullName}" prompt template not found on disk: ${sDef.prompt_template}`);
                    }
