/**
 * Zod Schema for validation of skill.yaml
 */
export const JudgmentTypeSchema = z.enum(['predicate', 'categorical', 'evaluation']);
export const JudgmentDefinitionSchema = z.object({
    type: JudgmentTypeSchema,
